PRAGMA foreign_keys = ON;

-- Samostatný test bez přiřazení studentovi. Po nahrání migrace jej přiřaď Janovi v administraci.

-- Tento soubor není běžný upload do knihovny: jde o D1 SQL migraci pro původní self-check engine.

INSERT OR IGNORE INTO self_check_tests (id, slug, version, title, description, subject, topic, level, estimated_minutes, status)

VALUES ('limity-funkci-jan-v1','limity-funkci-jan','1','Limity funkcí — navazující self-check (30 úloh)','30 úloh / 66 bodů / cca 40–50 minut. Navazuje na interaktivní zápis Limity funkcí: hodnota v bodě a okolí, jednostranné limity, neurčité tvary 0/0, krácení, racionalizace, limita v nekonečnu a ε–δ. Navíc rozšiřující VŠ příklady na sin, exp, ln. Po vyhodnocení je vidět rozbor chyb; lze vyhodnotit i předčasně jen odpovězené úlohy.','Matematika','Limity funkcí','SŠ/VŠ','45','published');

INSERT OR IGNORE INTO self_check_questions (id, test_id, position, prompt, options_json, correct_answer, explanation, points) VALUES

  ('limity-funkci-jan-v1-q01', 'limity-funkci-jan-v1', '1', '{"instruction": "Pro x ≠ 1 platí daný předpis, ale f(1) není definováno. Urči limitu.", "math": "\\lim_{x\\to1}\\frac{x^2-1}{x-1}", "category": "01 / Pochopení limity", "hint": "Zkus rozložit rozdíl čtverců."}', '[{"id": "a", "label": "[[math:0]]"}, {"id": "b", "label": "[[math:1]]"}, {"id": "c", "label": "[[math:2]]"}, {"id": "d", "label": "Limita neexistuje"}]', 'c', 'Pro x≠1 zkrátíme (x−1) a dostaneme x+1. V okolí jedničky se hodnoty blíží k 2; samotná díra nevadí.', '2'),
  ('limity-funkci-jan-v1-q02', 'limity-funkci-jan-v1', '2', '{"instruction": "Funkce je v okolí bodu daná předpisem f(x)=x+1, ale definujeme f(1)=7. Co platí?", "math": "\\lim_{x\\to1}f(x)\\;=?", "category": "01 / Pochopení limity", "hint": "Rozliš hodnotu v bodě a chování v okolí."}', '[{"id": "a", "label": "[[math:7]]"}, {"id": "b", "label": "[[math:2]]"}, {"id": "c", "label": "Neexistuje"}, {"id": "d", "label": "[[math:1]]"}]', 'b', 'Izolovaná změna hodnoty f(1) nemění limitu, protože pro x→1 (x≠1) se funkce chová jako x+1.', '1'),
  ('limity-funkci-jan-v1-q03', 'limity-funkci-jan-v1', '3', '{"instruction": "Které tvrzení o konečné oboustranné limitě je správné?", "math": "\\lim_{x\\to a}f(x)=L", "category": "01 / Pochopení limity", "hint": "Přiblížení k a probíhá ze dvou stran."}', '[{"id": "a", "label": "Musí být definováno f(a)."}, {"id": "b", "label": "Musí platit f(a)=L."}, {"id": "c", "label": "Musí být obě jednostranné limity rovny L."}, {"id": "d", "label": "Funkce musí být spojitá na celé ℝ."}]', 'c', 'Konečná oboustranná limita je L právě tehdy, když levá i pravá limita existují a mají tutéž hodnotu L.', '1'),
  ('limity-funkci-jan-v1-q04', 'limity-funkci-jan-v1', '4', '{"instruction": "Přímým dosazením do zlomku dostaneš 0/0. Jaký je správný závěr?", "math": "\\frac{0}{0}", "category": "01 / Pochopení limity", "hint": "Neurčitý tvar není číslo."}', '[{"id": "a", "label": "Limita je 0."}, {"id": "b", "label": "Limita je 1."}, {"id": "c", "label": "Limita vždy neexistuje."}, {"id": "d", "label": "Přímé dosazení nerozhodlo; je třeba další úprava."}]', 'd', '0/0 je neurčitý tvar, nikoli výsledná hodnota limity. Vhodná metoda závisí na předpisu.', '1'),
  ('limity-funkci-jan-v1-q05', 'limity-funkci-jan-v1', '5', '{"instruction": "Jak se projeví spojitost funkce v bodě a?", "math": "f\\text{ je spojitá v }a", "category": "01 / Pochopení limity", "hint": "Vzpomeň si na větu o limitě spojité funkce."}', '[{"id": "a", "label": "[[math:\\lim_{x\\to a}f(x)=f(a)]]"}, {"id": "b", "label": "[[math:\\lim_{x\\to a}f(x)=0]]"}, {"id": "c", "label": "[[math:\\lim_{x\\to a}f(x)=+\\infty]]"}, {"id": "d", "label": "Limita neexistuje"}]', 'a', 'V bodě spojitosti je limita rovna hodnotě funkce v daném bodě.', '1'),
  ('limity-funkci-jan-v1-q06', 'limity-funkci-jan-v1', '6', '{"instruction": "Zleva se funkce blíží k 1 a zprava k 3. Co je její oboustranná limita?", "math": "\\lim_{x\\to0^-}f(x)=1,\\qquad \\lim_{x\\to0^+}f(x)=3", "category": "02 / Jednostranné limity", "hint": "Porovnej výsledky obou stran."}', '[{"id": "a", "label": "Je 1."}, {"id": "b", "label": "Je 2."}, {"id": "c", "label": "Je 3."}, {"id": "d", "label": "Neexistuje."}]', 'd', 'Jednostranné limity jsou různá čísla. Proto oboustranná limita neexistuje.', '1'),
  ('limity-funkci-jan-v1-q07', 'limity-funkci-jan-v1', '7', '{"instruction": "Urči limitu zleva.", "math": "\\lim_{x\\to0^-}\\frac1x", "category": "02 / Jednostranné limity", "hint": "Zleva znamená záporná x."}', '[{"id": "a", "label": "[[math:+\\infty]]"}, {"id": "b", "label": "[[math:-\\infty]]"}, {"id": "c", "label": "[[math:0]]"}, {"id": "d", "label": "Neexistuje ani jednostranná nevlastní limita"}]', 'b', 'Pro záporná x blízká nule je 1/x záporné a jeho absolutní hodnota roste bez omezení.', '2'),
  ('limity-funkci-jan-v1-q08', 'limity-funkci-jan-v1', '8', '{"instruction": "Urči limitu zprava.", "math": "\\lim_{x\\to0^+}\\frac1{x^2}", "category": "02 / Jednostranné limity", "hint": "Čtverec záporného i kladného čísla je kladný."}', '[{"id": "a", "label": "[[math:-\\infty]]"}, {"id": "b", "label": "[[math:+\\infty]]"}, {"id": "c", "label": "[[math:0]]"}, {"id": "d", "label": "[[math:1]]"}]', 'b', 'Druhá mocnina je kladná a blíží se k 0+, proto její převrácená hodnota roste do +∞.', '2'),
  ('limity-funkci-jan-v1-q09', 'limity-funkci-jan-v1', '9', '{"instruction": "Která oboustranná limita existuje jako konečné reálné číslo?", "math": "x\\to0", "category": "02 / Jednostranné limity", "hint": "Dívej se na obě strany."}', '[{"id": "a", "label": "[[math:\\lim_{x\\to0}\\frac1x]]"}, {"id": "b", "label": "[[math:\\lim_{x\\to0}\\frac{|x|}{x}]]"}, {"id": "c", "label": "[[math:\\lim_{x\\to0}|x|]]"}, {"id": "d", "label": "[[math:\\lim_{x\\to0}\\frac1{x^2}]]"}]', 'c', '|x| se z obou stran blíží k 0. Ostatní možnosti nemají konečnou oboustrannou limitu.', '2'),
  ('limity-funkci-jan-v1-q10', 'limity-funkci-jan-v1', '10', '{"instruction": "Urči limitu ze záporných hodnot x.", "math": "\\lim_{x\\to0^-}\\frac{|x|}{x}", "category": "02 / Jednostranné limity", "hint": "Rozepiš absolutní hodnotu na intervalu x<0."}', '[{"id": "a", "label": "[[math:-1]]"}, {"id": "b", "label": "[[math:0]]"}, {"id": "c", "label": "[[math:1]]"}, {"id": "d", "label": "Neexistuje"}]', 'a', 'Pro x<0 platí |x|=−x, takže |x|/x=−1.', '2'),
  ('limity-funkci-jan-v1-q11', 'limity-funkci-jan-v1', '11', '{"instruction": "Využij spojitost polynomu a dosaď.", "math": "\\lim_{x\\to2}(3x^2-2)", "category": "03 / Algebraické výpočty", "hint": "Pozor na druhou mocninu."}', '[{"id": "a", "label": "[[math:4]]"}, {"id": "b", "label": "[[math:8]]"}, {"id": "c", "label": "[[math:10]]"}, {"id": "d", "label": "[[math:12]]"}]', 'c', 'Po dosazení x=2: 3·2²−2=12−2=10.', '1'),
  ('limity-funkci-jan-v1-q12', 'limity-funkci-jan-v1', '12', '{"instruction": "Rozlož čitatele a vypočítej limitu.", "math": "\\lim_{x\\to3}\\frac{x^2-9}{x-3}", "category": "03 / Algebraické výpočty", "hint": "Rozdíl druhých mocnin."}', '[{"id": "a", "label": "[[math:0]]"}, {"id": "b", "label": "[[math:3]]"}, {"id": "c", "label": "[[math:6]]"}, {"id": "d", "label": "Neexistuje"}]', 'c', 'x²−9=(x−3)(x+3). Pro x≠3 vyjde x+3 a limita je 6.', '2'),
  ('limity-funkci-jan-v1-q13', 'limity-funkci-jan-v1', '13', '{"instruction": "Po rozkladu čitatele i jmenovatele urči limitu.", "math": "\\lim_{x\\to2}\\frac{x^2-4}{x^2-3x+2}", "category": "03 / Algebraické výpočty", "hint": "Jmenovatel (x−1)(x−2)."}', '[{"id": "a", "label": "[[math:2]]"}, {"id": "b", "label": "[[math:4]]"}, {"id": "c", "label": "[[math:6]]"}, {"id": "d", "label": "[[math:+\\infty]]"}]', 'b', '(x²−4)/[(x−1)(x−2)] = (x+2)/(x−1) pro x≠2,1. Po dosazení x=2 dostaneme 4.', '3'),
  ('limity-funkci-jan-v1-q14', 'limity-funkci-jan-v1', '14', '{"instruction": "Rozlož rozdíl třetích mocnin.", "math": "\\lim_{x\\to2}\\frac{x^3-8}{x-2}", "category": "03 / Algebraické výpočty", "hint": "a³−b³=(a−b)(a²+ab+b²)."}', '[{"id": "a", "label": "[[math:4]]"}, {"id": "b", "label": "[[math:8]]"}, {"id": "c", "label": "[[math:12]]"}, {"id": "d", "label": "[[math:16]]"}]', 'c', 'x³−8=(x−2)(x²+2x+4). Po vykrácení dostaneme 4+4+4=12.', '3'),
  ('limity-funkci-jan-v1-q15', 'limity-funkci-jan-v1', '15', '{"instruction": "Odstraň neurčitý tvar pomocí sdruženého výrazu.", "math": "\\lim_{x\\to0}\\frac{\\sqrt{x+9}-3}{x}", "category": "03 / Algebraické výpočty", "hint": "Použij (a−b)(a+b)=a²−b²."}', '[{"id": "a", "label": "[[math:\\frac13]]"}, {"id": "b", "label": "[[math:\\frac16]]"}, {"id": "c", "label": "[[math:\\frac19]]"}, {"id": "d", "label": "[[math:0]]"}]', 'b', 'Po rozšíření (√(x+9)+3) vznikne 1/(√(x+9)+3); limita je 1/6.', '3'),
  ('limity-funkci-jan-v1-q16', 'limity-funkci-jan-v1', '16', '{"instruction": "Odstraň odmocninu rozšířením.", "math": "\\lim_{x\\to0}\\frac{\\sqrt{x+4}-2}{x}", "category": "04 / Další neurčité tvary", "hint": "Vynásob sdruženým výrazem."}', '[{"id": "a", "label": "[[math:\\frac14]]"}, {"id": "b", "label": "[[math:\\frac12]]"}, {"id": "c", "label": "[[math:2]]"}, {"id": "d", "label": "[[math:4]]"}]', 'a', 'Racionalizací dostaneme 1/(√(x+4)+2), což pro x→0 dává 1/4.', '2'),
  ('limity-funkci-jan-v1-q17', 'limity-funkci-jan-v1', '17', '{"instruction": "Použij základní goniometrickou limitu.", "math": "\\lim_{x\\to0}\\frac{\\sin(3x)}{\\sin(5x)}", "category": "04 / Další neurčité tvary", "hint": "lim sin(t)/t = 1 pro t→0 (radiány)."}', '[{"id": "a", "label": "[[math:\\frac53]]"}, {"id": "b", "label": "[[math:\\frac35]]"}, {"id": "c", "label": "[[math:0]]"}, {"id": "d", "label": "[[math:1]]"}]', 'b', '(sin 3x)/(3x)→1 a (sin 5x)/(5x)→1, tedy výsledek je 3/5.', '3'),
  ('limity-funkci-jan-v1-q18', 'limity-funkci-jan-v1', '18', '{"instruction": "Použij standardní exponenciální limitu.", "math": "\\lim_{x\\to0}\\frac{e^{2x}-1}{3x}", "category": "04 / Další neurčité tvary", "hint": "lim (e^u−1)/u = 1."}', '[{"id": "a", "label": "[[math:\\frac23]]"}, {"id": "b", "label": "[[math:\\frac32]]"}, {"id": "c", "label": "[[math:2]]"}, {"id": "d", "label": "[[math:0]]"}]', 'a', 'Po substituci u=2x platí (e^u−1)/u→1. Zůstane násobek 2/3.', '3'),
  ('limity-funkci-jan-v1-q19', 'limity-funkci-jan-v1', '19', '{"instruction": "Použij standardní logaritmickou limitu.", "math": "\\lim_{x\\to0}\\frac{\\ln(1+4x)}{2x}", "category": "04 / Další neurčité tvary", "hint": "lim ln(1+u)/u=1."}', '[{"id": "a", "label": "[[math:\\frac12]]"}, {"id": "b", "label": "[[math:1]]"}, {"id": "c", "label": "[[math:2]]"}, {"id": "d", "label": "[[math:4]]"}]', 'c', 'Polož u=4x: ln(1+u)/u→1 a celkový násobek je 4/2=2.', '3'),
  ('limity-funkci-jan-v1-q20', 'limity-funkci-jan-v1', '20', '{"instruction": "Urči pomocí známé goniometrické limity.", "math": "\\lim_{x\\to0}\\frac{1-\\cos x}{x^2}", "category": "04 / Další neurčité tvary", "hint": "Použij 1−cos x=2 sin²(x/2)."}', '[{"id": "a", "label": "[[math:0]]"}, {"id": "b", "label": "[[math:\\frac12]]"}, {"id": "c", "label": "[[math:1]]"}, {"id": "d", "label": "[[math:+\\infty]]"}]', 'b', '1−cos x=2sin²(x/2). Limita je [2(x/2)²]/x²=1/2, protože sin u/u→1.', '3'),
  ('limity-funkci-jan-v1-q21', 'limity-funkci-jan-v1', '21', '{"instruction": "Vypočítej limitu v nekonečnu dělením x.", "math": "\\lim_{x\\to+\\infty}\\frac{2x+3}{x+1}", "category": "05 / Limity v nekonečnu", "hint": "Nejvyšší mocnina je x."}', '[{"id": "a", "label": "[[math:0]]"}, {"id": "b", "label": "[[math:1]]"}, {"id": "c", "label": "[[math:2]]"}, {"id": "d", "label": "[[math:3]]"}]', 'c', 'Poděl čitatel a jmenovatel x: (2+3/x)/(1+1/x)→2.', '2'),
  ('limity-funkci-jan-v1-q22', 'limity-funkci-jan-v1', '22', '{"instruction": "Vypočítej limitu racionální funkce.", "math": "\\lim_{x\\to+\\infty}\\frac{3x^2-x+1}{2x^2+5}", "category": "05 / Limity v nekonečnu", "hint": "Stupeň čitatele a jmenovatele je stejný."}', '[{"id": "a", "label": "[[math:\\frac23]]"}, {"id": "b", "label": "[[math:\\frac32]]"}, {"id": "c", "label": "[[math:3]]"}, {"id": "d", "label": "[[math:0]]"}]', 'b', 'Dělíme x². Zůstane podíl vedoucích koeficientů 3/2.', '2'),
  ('limity-funkci-jan-v1-q23', 'limity-funkci-jan-v1', '23', '{"instruction": "Rozhodni limitu, když je stupeň jmenovatele vyšší.", "math": "\\lim_{x\\to+\\infty}\\frac{2x+1}{x^2+1}", "category": "05 / Limity v nekonečnu", "hint": "Porovnej nejvyšší mocniny."}', '[{"id": "a", "label": "[[math:0]]"}, {"id": "b", "label": "[[math:2]]"}, {"id": "c", "label": "[[math:+\\infty]]"}, {"id": "d", "label": "[[math:1]]"}]', 'a', 'Jmenovatel roste kvadraticky, čitatel lineárně. Po dělení x² vyjde 0.', '2'),
  ('limity-funkci-jan-v1-q24', 'limity-funkci-jan-v1', '24', '{"instruction": "Urči nevlastní limitu v +∞.", "math": "\\lim_{x\\to+\\infty}\\frac{x^3-x}{2x^2+1}", "category": "05 / Limity v nekonečnu", "hint": "Stupeň čitatele je o jedna vyšší."}', '[{"id": "a", "label": "[[math:0]]"}, {"id": "b", "label": "[[math:\\frac12]]"}, {"id": "c", "label": "[[math:-\\infty]]"}, {"id": "d", "label": "[[math:+\\infty]]"}]', 'd', 'Dominantní poměr je x³/(2x²)=x/2. Při x→+∞ roste bez omezení.', '2'),
  ('limity-funkci-jan-v1-q25', 'limity-funkci-jan-v1', '25', '{"instruction": "Rozhodni limitu ve směru −∞.", "math": "\\lim_{x\\to-\\infty}\\frac{x}{\\sqrt{x^2+1}}", "category": "05 / Limity v nekonečnu", "hint": "Pozor: √(x²)=|x|, nikoliv vždy x."}', '[{"id": "a", "label": "[[math:1]]"}, {"id": "b", "label": "[[math:-1]]"}, {"id": "c", "label": "[[math:0]]"}, {"id": "d", "label": "[[math:+\\infty]]"}]', 'b', '√(x²+1)=|x|√(1+1/x²). Pro x→−∞ je |x|=−x, proto podíl směřuje k −1.', '3'),
  ('limity-funkci-jan-v1-q26', 'limity-funkci-jan-v1', '26', '{"instruction": "Pro f(x)=2x+1 a a=1 zvol podmínku zajišťující chybu menší než ε.", "math": "|f(x)-3|=2|x-1|", "category": "06 / Definice a přesnost", "hint": "Doplň nerovnost 2δ≤ε."}', '[{"id": "a", "label": "[[math:0<\\delta\\leq\\frac{\\varepsilon}{2}]]"}, {"id": "b", "label": "[[math:\\delta\\geq2\\varepsilon]]"}, {"id": "c", "label": "[[math:\\delta=2\\varepsilon]]"}, {"id": "d", "label": "[[math:\\delta\\geq\\varepsilon]]"}]', 'a', 'Z |f(x)−3|=2|x−1| a |x−1|<δ plyne |f(x)−3|<2δ. Stačí zvolit 0<δ≤ε/2.', '3'),
  ('limity-funkci-jan-v1-q27', 'limity-funkci-jan-v1', '27', '{"instruction": "Rozhodni, zda zvolené δ splňuje podmínku pro dané ε.", "math": "f(x)=2x+1,\\quad\\varepsilon=0{,}4,\\quad\\delta=0{,}2", "category": "06 / Definice a přesnost", "hint": "U podmínek jde o ostré nerovnosti pro x."}', '[{"id": "a", "label": "Ano, pro všechna 0<|x−1|<δ."}, {"id": "b", "label": "Ne, δ musí být menší než ε/4."}, {"id": "c", "label": "Ne, protože δ=ε/2 je zakázáno."}, {"id": "d", "label": "Pouze pokud x>1."}]', 'a', 'Platí 2δ=0,4=ε. Protože okolí je otevřené (<δ), výstupní chyba bude skutečně <ε.', '3'),
  ('limity-funkci-jan-v1-q28', 'limity-funkci-jan-v1', '28', '{"instruction": "Rozhodni, zda zvolené δ splňuje podmínku pro dané ε.", "math": "f(x)=2x+1,\\quad\\varepsilon=0{,}4,\\quad\\delta=0{,}3", "category": "06 / Definice a přesnost", "hint": "Ověř, zda 2δ≤ε."}', '[{"id": "a", "label": "Ano, vždy."}, {"id": "b", "label": "Ne, může nastat chyba větší než ε."}, {"id": "c", "label": "Ano, protože δ je menší než ε."}, {"id": "d", "label": "Není rozhodnutelné."}]', 'b', 'Pro δ=0,3 může být |x−1| například 0,25; pak |f(x)−3|=0,5>ε=0,4.', '3'),
  ('limity-funkci-jan-v1-q29', 'limity-funkci-jan-v1', '29', '{"instruction": "Co vyjadřuje podmínka 0<|x−a|<δ v definici limity?", "math": "0<|x-a|<\\delta", "category": "06 / Definice a přesnost", "hint": "Všimni si znaménka 0<."}', '[{"id": "a", "label": "Zahrnuje jen bod x=a."}, {"id": "b", "label": "Vylučuje bod a a omezuje vzdálenost vstupu od a."}, {"id": "c", "label": "Požaduje f(a)=L."}, {"id": "d", "label": "Stanovuje vzdálenost hodnoty funkce od L."}]', 'b', 'Je to proražené δ-okolí bodu a: sledujeme okolí, nikoli samotný bod.', '2'),
  ('limity-funkci-jan-v1-q30', 'limity-funkci-jan-v1', '30', '{"instruction": "Která formulace správně zachycuje definici konečné limity?", "math": "\\lim_{x\\to a}f(x)=L", "category": "06 / Definice a přesnost", "hint": "Rozhoduje pořadí kvantifikátorů."}', '[{"id": "a", "label": "Existuje jediné ε pro všechna δ."}, {"id": "b", "label": "Pro všechna δ>0 existuje ε>0 bez dalších podmínek."}, {"id": "c", "label": "Pro každé ε>0 existuje δ>0 tak, že 0<|x−a|<δ implikuje |f(x)−L|<ε."}, {"id": "d", "label": "Stačí zjistit f(a)=L."}]', 'c', 'Definice pracuje v pořadí ∀ε>0 ∃δ>0 a stanoví, že dostatečně malé proražené okolí vstupu vede k požadované přesnosti výstupu.', '3');